import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class UserProfileServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserProfileServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String userId = req.getParameter("id");
        String fields = req.getParameter("fields");

        if (userId == null || userId.isEmpty()) {
            resp.sendError(400, "Missing id parameter");
            return;
        }

        // Validate userId is numeric
        if (!userId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid id format");
            return;
        }

        // fields parameter allows caller to specify columns to return
        // defaults to safe set if not provided
        String columnList = "username, email, created_at";
        if (fields != null && !fields.isEmpty()) {
            // Basic sanitization - remove obvious dangerous chars
            fields = fields.replace(";", "").replace("--", "");
            columnList = fields;
        }

        String query = "SELECT " + columnList + " FROM user_profiles WHERE user_id = " + userId;
        log.info("Executing query for user: " + userId);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("{\"results\":[");
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",");
                json.append("{");
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) json.append(",");
                    json.append("\"").append(meta.getColumnName(i)).append("\":");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("]}");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST updates profile - uses PreparedStatement (safe)
        String userId = req.getParameter("id");
        String newEmail = req.getParameter("email");

        if (userId == null || !userId.matches("^[0-9]+$")) {
            resp.sendError(400, "Invalid id");
            return;
        }

        String update = "UPDATE user_profiles SET email = ? WHERE user_id = ?";
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(update)) {
            ps.setString(1, newEmail);
            ps.setInt(2, Integer.parseInt(userId));
            ps.executeUpdate();
            resp.getWriter().write("{\"status\":\"updated\"}");
        } catch (SQLException e) {
            resp.sendError(500, "Internal error");
        }
    }
}
